cd /app && cat > output/assets/styles.css <<'CSS'
:root{
  color-scheme: light;
  --bg: oklch(0.99 0 0);
  --panel: oklch(1 0 0);
  --text: oklch(0.16 0.02 258);
  --muted: oklch(0.55 0.02 258);
  --muted2: oklch(0.70 0.02 258);
  --border: oklch(0.92 0.01 258);
  --shadow: 0 10px 30px oklch(0.25 0.02 258 / 0.06);
  --blue: oklch(0.54 0.20 255);
  --blue2: oklch(0.60 0.18 255);
  --green: #16c784;
  --red: #ea3943;
  --amber: oklch(0.78 0.14 80);
  --radius: 14px;
  --r2: 10px;
  --font: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --s1: .25rem;
  --s2: .5rem;
  --s3: .75rem;
  --s4: 1rem;
  --s5: 1.25rem;
  --s6: 1.5rem;
  --s7: 2rem;
  --s8: 2.5rem;
}

*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  font-family:var(--font);
  background:linear-gradient(180deg, oklch(0.985 0.01 255) 0%, var(--bg) 16%, var(--bg) 100%);
  color:var(--text);
}

.skip{position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden}
.skip:focus{left:16px;top:16px;width:auto;height:auto;padding:.5rem .75rem;background:var(--panel);border:1px solid var(--border);border-radius:10px;box-shadow:var(--shadow);z-index:50}

a{color:inherit}

.num{font-variant-numeric: tabular-nums; font-family: var(--mono)}
.muted{color:var(--muted)}

.top{position:sticky;top:0;z-index:20;backdrop-filter:saturate(180%) blur(10px);background:oklch(0.99 0.01 255 / .82);border-bottom:1px solid var(--border)}
.top__inner{display:flex;align-items:center;gap:var(--s6);padding:14px 20px;max-width:1600px;margin:0 auto}

.brand{display:flex;align-items:center;gap:12px;min-width:240px}
.brand__mark{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg, var(--blue) 0%, var(--blue2) 60%, oklch(0.72 .13 250) 100%);color:white;display:grid;place-items:center;font-weight:800;letter-spacing:.06em;font-size:12px}
.brand__name{font-weight:700;line-height:1.1}
.brand__sub{font-size:12px;color:var(--muted);margin-top:2px}

.nav{display:flex;align-items:center;gap:6px;flex:1}
.nav__link{padding:10px 10px;border-radius:10px;text-decoration:none;color:var(--muted);font-weight:600;font-size:13px}
.nav__link:hover{background:oklch(0.97 0.01 255);color:var(--text)}
.nav__link.is-active{background:oklch(0.965 0.02 255);color:var(--text);box-shadow:inset 0 0 0 1px var(--border)}
.nav__more{padding:10px 10px;border-radius:10px;border:1px solid var(--border);background:var(--panel);color:var(--text);font-weight:600;font-size:13px}
.nav__more:hover{border-color:oklch(0.88 0.02 255)}

.auth{display:flex;gap:10px}
.btn{border:1px solid var(--border);background:var(--panel);color:var(--text);font-weight:700;font-size:13px;border-radius:12px;padding:10px 12px;cursor:pointer;transition:150ms ease}
.btn:hover{transform:translateY(-1px);box-shadow:0 10px 20px oklch(0.25 0.02 258 / 0.06)}
.btn:active{transform:translateY(0)}
.btn--primary{background:linear-gradient(135deg, var(--blue) 0%, var(--blue2) 70%);border-color:transparent;color:white}
.btn--ghost{background:transparent}

.stats{border-top:1px solid var(--border);background:linear-gradient(180deg, oklch(0.99 0.01 255 / .78) 0%, oklch(0.99 0 0 / .72) 100%)}
.stats__inner{max-width:1600px;margin:0 auto;padding:10px 20px;display:grid;grid-template-columns: repeat(4, minmax(160px, 1fr)) minmax(260px, 360px);gap:10px;align-items:stretch}
.stat{background:var(--panel);border:1px solid var(--border);border-radius:var(--r2);padding:10px 12px;display:flex;flex-direction:column;gap:4px}
.stat__k{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.stat__v{display:flex;align-items:baseline;gap:10px;font-weight:700}

.stats__right{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.mini{background:var(--panel);border:1px solid var(--border);border-radius:var(--r2);padding:10px 12px;display:flex;flex-direction:column;gap:4px}
.mini__k{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.mini__v{display:flex;align-items:baseline;gap:10px;font-weight:700}

.badge{font-size:12px;font-weight:700;color:oklch(0.32 0.03 258);background:oklch(0.95 0.02 90);border:1px solid oklch(0.90 0.03 90);padding:2px 8px;border-radius:999px}

.chg{font-variant-numeric: tabular-nums;font-family:var(--mono);font-size:12px;font-weight:700}
.chg--pos{color:var(--green)}
.chg--neg{color:var(--red)}

.promo{border-top:1px solid var(--border)}
.promo__inner{max-width:1600px;margin:0 auto;padding:10px 20px;display:grid;grid-template-columns:40px 1fr 40px;gap:10px;align-items:center}
.promo__track{background:var(--panel);border:1px solid var(--border);border-radius:var(--radius);padding:12px 14px;box-shadow:var(--shadow);min-height:46px;display:flex;align-items:center;justify-content:space-between;gap:12px}
.promo__text{font-weight:700}
.promo__meta{font-size:12px;color:var(--muted);font-family:var(--mono)}
.iconbtn{width:40px;height:40px;border-radius:12px;border:1px solid var(--border);background:var(--panel);cursor:pointer;font-size:18px;line-height:1}
.iconbtn:hover{border-color:oklch(0.88 0.02 255)}

.ai{border-top:1px solid var(--border)}
.ai__inner{max-width:1600px;margin:0 auto;padding:10px 20px;display:flex;flex-direction:column;gap:10px}
.ai__prompt{display:flex;align-items:center;gap:10px}
.ai__pill{font-size:11px;text-transform:uppercase;letter-spacing:.08em;font-weight:800;color:oklch(0.30 0.04 258);background:oklch(0.95 0.02 255);border:1px solid var(--border);padding:4px 8px;border-radius:999px}
.ai__topic{font-weight:650}
.ai__qs{display:flex;gap:8px;flex-wrap:wrap}

.chip{border:1px solid var(--border);background:var(--panel);color:var(--text);padding:8px 10px;border-radius:999px;font-size:12px;font-weight:650;cursor:pointer;transition:150ms ease}
.chip:hover{transform:translateY(-1px);box-shadow:0 10px 20px oklch(0.25 0.02 258 / 0.06)}
.chip:active{transform:translateY(0)}
.chip--sm{padding:6px 10px;font-size:12px}

.main{max-width:1600px;margin:0 auto;padding:18px 20px 40px}

.filters{display:flex;flex-direction:column;gap:10px;margin-top:10px}
.tabs{display:flex;gap:8px;flex-wrap:wrap}
.tab{border:1px solid var(--border);background:var(--panel);padding:10px 12px;border-radius:999px;font-weight:750;font-size:13px;cursor:pointer}
.tab:hover{border-color:oklch(0.88 0.02 255)}
.tab.is-active{background:oklch(0.965 0.02 255);border-color:oklch(0.85 0.03 255);color:var(--text)}
.tab--more{font-weight:700;color:var(--muted)}

.tabs--sub .tab2{border:1px solid var(--border);background:transparent;padding:8px 10px;border-radius:999px;font-weight:750;font-size:12px;color:var(--muted);cursor:pointer}
.tabs--sub .tab2:hover{background:oklch(0.97 0.01 255);color:var(--text)}
.tabs--sub .tab2.is-active{background:oklch(0.965 0.02 255);color:var(--text)}

.panel{margin-top:14px;background:var(--panel);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);overflow:hidden}
.panel__head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;padding:16px 16px 12px;border-bottom:1px solid var(--border)}
.panel__title h1{font-size:18px;margin:0}
.panel__sub{color:var(--muted);font-size:12px;margin-top:4px}

.controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:flex-end}
.seg{display:flex;border:1px solid var(--border);border-radius:12px;overflow:hidden;background:oklch(0.98 0.01 255)}
.seg__btn{border:0;background:transparent;padding:10px 12px;font-weight:800;font-size:12px;cursor:pointer;color:var(--muted)}
.seg__btn.is-active{background:var(--panel);color:var(--text)}

.panel__subrow{padding:12px 16px;border-bottom:1px solid var(--border);background:linear-gradient(180deg, oklch(0.985 0.01 255) 0%, var(--panel) 100%)}
.indexrow{display:flex;align-items:center;justify-content:space-between;gap:16px}
.indexrow__left{display:flex;align-items:baseline;gap:14px}
.indexrow__name{font-weight:800}
.indexrow__price{font-size:14px;font-weight:900}
.indexrow__right{display:flex;gap:14px;flex-wrap:wrap}
.pct{display:flex;align-items:baseline;gap:8px}
.pct__k{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}

.dropdowns{padding:0 16px}
.dropdown{margin:10px 0 0;background:oklch(0.985 0.01 255);border:1px solid var(--border);border-radius:var(--r2);padding:12px}
.dropdown__title{font-weight:850;margin-bottom:10px}
.dropdown__grid{display:grid;grid-template-columns: 1.4fr 1fr .8fr 1fr;gap:12px;align-items:end}
.field{display:flex;flex-direction:column;gap:6px}
.field__k{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;font-weight:800}
.field__hint{font-size:11px;color:var(--muted)}
.input{height:38px;border-radius:12px;border:1px solid var(--border);padding:0 10px;font-family:var(--font);font-size:13px;background:var(--panel)}
.input:focus{outline:2px solid oklch(0.75 0.12 255 / .55);outline-offset:1px}
.quick{display:flex;gap:8px;flex-wrap:wrap}

.cols{display:flex;gap:10px;flex-wrap:wrap}
.check{display:flex;align-items:center;gap:8px;font-weight:700;color:var(--text);background:var(--panel);border:1px solid var(--border);border-radius:999px;padding:8px 10px}
.check input{accent-color: var(--blue)}

.tablewrap{overflow:auto;max-height:620px}
.table{width:100%;border-collapse:separate;border-spacing:0}
.th{position:sticky;top:0;background:var(--panel);z-index:5;border-bottom:1px solid var(--border);font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.th--rank{width:54px}
.th--name{min-width:260px}
.th--num{min-width:130px;text-align:right}
.th--spark{min-width:170px}
.thbtn{width:100%;text-align:left;border:0;background:transparent;color:inherit;font:inherit;padding:12px 12px;cursor:pointer;font-weight:900}
.th--num .thbtn{text-align:right}

.table td{padding:11px 12px;border-bottom:1px solid var(--border);font-size:13px;vertical-align:middle}
.table tbody tr:hover{background:oklch(0.985 0.01 255)}
.td--rank{color:var(--muted);font-family:var(--mono);font-size:12px}
.namecell{display:flex;align-items:center;gap:10px}
.coin{width:28px;height:28px;border-radius:10px;background:linear-gradient(135deg, oklch(0.92 0.05 255) 0%, oklch(0.96 0.02 255) 60%, oklch(0.95 0.03 200) 100%);border:1px solid var(--border);display:grid;place-items:center;font-weight:900;font-size:11px;color:oklch(0.25 0.06 255)}
.sym{font-family:var(--mono);font-size:12px;color:var(--muted);margin-top:2px}
.nm{font-weight:850;line-height:1.1}
.right{text-align:right}
.pctv{font-family:var(--mono);font-variant-numeric:tabular-nums;font-weight:800}

.spark{width:140px;height:26px}

.pager{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 16px}
.pager__left{color:var(--muted);font-size:12px}
.pager__right{display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end}
.pbtn{border:1px solid var(--border);background:var(--panel);border-radius:10px;padding:8px 10px;font-weight:850;font-size:12px;cursor:pointer}
.pbtn:hover{border-color:oklch(0.88 0.02 255)}
.pbtn.is-active{background:oklch(0.965 0.02 255);border-color:oklch(0.85 0.03 255)}
.pbtn.is-ghost{background:transparent;color:var(--muted)}

.summary{margin-top:14px;background:var(--panel);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);padding:16px}
.summary__head{display:flex;align-items:center;justify-content:space-between;gap:12px}
.summary h2{margin:0;font-size:16px}
.summary__p{margin:10px 0 0;color:oklch(0.25 0.02 258);line-height:1.6}
.link{border:0;background:transparent;color:var(--blue);font-weight:850;cursor:pointer}
.link:hover{text-decoration:underline}
.more{margin-top:14px}
.more__grid{display:grid;grid-template-columns:repeat(4, minmax(180px, 1fr));gap:10px}
.more__card{border:1px solid var(--border);border-radius:var(--r2);padding:12px;background:oklch(0.985 0.01 255)}
.more__k{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;font-weight:900}
.more__v{font-weight:900;margin-top:6px}
.more__h{color:var(--muted);font-size:12px;margin-top:4px}

.info{margin-top:14px;background:var(--panel);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);padding:16px;line-height:1.65}
.info h2{margin:0 0 10px;font-size:16px}
.info h3{margin:14px 0 6px;font-size:13px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}
.info p{margin:0 0 10px;color:oklch(0.25 0.02 258)}

.footer{margin-top:22px;border-top:1px solid var(--border);background:oklch(0.99 0 0)}
.footer__inner{max-width:1600px;margin:0 auto;padding:22px 20px}
.footer__cols{display:grid;grid-template-columns:repeat(4, minmax(160px, 1fr));gap:18px}
.fcol__k{font-weight:950;margin-bottom:10px}
.fcol__a{display:block;text-decoration:none;color:var(--muted);padding:6px 0}
.fcol__a:hover{color:var(--text)}
.footer__bottom{margin-top:16px;padding-top:14px;border-top:1px solid var(--border);display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}

/* Column visibility toggles */
.hide-col-h1 .col-h1, .hide-col-h1 td[data-col="h1"]{display:none}
.hide-col-h24 .col-h24, .hide-col-h24 td[data-col="h24"]{display:none}
.hide-col-d7 .col-d7, .hide-col-d7 td[data-col="d7"]{display:none}
.hide-col-marketCap .col-marketCap, .hide-col-marketCap td[data-col="marketCap"]{display:none}
.hide-col-volume .col-volume, .hide-col-volume td[data-col="volume"]{display:none}
.hide-col-supply .col-supply, .hide-col-supply td[data-col="supply"]{display:none}
.hide-col-spark .col-spark, .hide-col-spark td[data-col="spark"]{display:none}

@media (max-width: 1100px){
  .top__inner{gap:12px}
  .brand{min-width:auto}
  .nav{display:none}
  .stats__inner{grid-template-columns:repeat(2, minmax(160px, 1fr))}
  .stats__right{grid-template-columns:1fr 1fr}
  .dropdown__grid{grid-template-columns:1fr 1fr}
  .more__grid{grid-template-columns:repeat(2, minmax(180px, 1fr))}
}
@media (max-width: 720px){
  .auth{display:none}
  .promo__inner{grid-template-columns:40px 1fr 40px}
  .tablewrap{max-height:540px}
  .panel__head{flex-direction:column;align-items:flex-start}
  .controls{justify-content:flex-start}
  .more__grid{grid-template-columns:1fr}
  .footer__cols{grid-template-columns:repeat(2, minmax(160px, 1fr))}
}
