  return String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

async function boot() {
  setActiveTabs();
  applyColumnVisibility();
  wireTabs();
  wireSort();
  wireToggles();
  wireReadMore();
  wirePromoCarousel();

  const res = await fetch('assets/coins.json');
  COINS = await res.json();

  // Start in Market Cap sort to match UI control
  state.sortKey = 'marketCap';
  state.sortDir = 'desc';

  updateSortIndicators();
  renderTable();
  renderPager();
}

boot();
